SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(10*10^9);Alarm(600);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");Attach("work/deg10/continuation_20261031b/Y228_shared/fast_hecke_11.m");load "work/deg10/continuation_20261031b/Y228_shared/fast_primitive_inverse.m";load "work/deg10/continuation_20261031b/Y228_shared/union_cases.m";
k:=GF(3);X:=MDX11(2,28,k);CC:=Curve(X);FF:=FunctionField(CC);F0,mp:=AlgorithmicFunctionField(FF);F:=RationalExtensionRepresentation(F0);assert Genus(F) eq 25;bc:=[F!mp(z):z in X`_coordinates];U:=F!mp(FF.1);V:=F!mp(FF.2);plane:=DefiningPolynomial(CC);OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);print "Y228_FAST_MODEL_READY",Degree(F),U eq F!BaseRing(F).1,V eq F.1,Cputime(tt);
function Get(E,P,Q) st:=Cputime();p:=Y228FastPrimitivePlace(plane,F,U,V,bc,DerickxNormalForm_bc(E,P,Q));print "Y228_FAST_GET",Degree(p),Cputime(st),Cputime(tt);return p;end function;
oldmodel:=eval Read("work/deg10/continuation_20261031b/Y228_shared/fast_inverse_old_model_snapshot.m");oldrec:=eval Read("work/deg10/continuation_20261031b/Y228_shared/fast_inverse_old_case8_snapshot_v2.m");assert oldrec[1] eq 8;assert [[ [Integers()!q:q in Coefficients(Numerator(v))],[Integers()!q:q in Coefficients(Denominator(v))]]:v in Coefficients(DefiningPolynomial(F))] eq oldmodel[1];
function Rat(v)return BaseRing(F)!PolynomialRing(k)!v[1]/(BaseRing(F)!PolynomialRing(k)!v[2]);end function;
function RestorePD(v)OO:=v[2] eq 1 select OF else OI;aa:=[F![Rat(c):c in f]:f in v[3]];II:=ideal<OO|aa>;assert #aa eq 2 and IsPrime(II);pp:=Place(II);assert Degree(pp) eq v[1];return pp;end function;
ci:=8;part:=UnionCases[ci][3][1];d,m,ky:=Explode(part);pol:=[v[2]:v in UnionFields|v[1] eq d][1];PK:=PolynomialRing(k);K<a>:=ext<k|PK!pol>;bb:=Evaluate(PK!ky[1..d],a);cc:=Evaluate(PK!ky[d+1..2*d],a);E:=EllipticCurve([K|0,cc,0,bb*(1-bb-cc),0]);P:=E![0,0];Q:=E![bb,bb];assert Order(Q) eq 28 and P ne 14*Q;ps:=Get(E,P,Q);pd:=Get(E,P,5*Q);op:=oldrec[3][1];oldps:=RestorePD(op[4]);oldpd:=RestorePD(op[5]);assert Ideal(ps) eq Ideal(oldps) and Ideal(pd) eq Ideal(oldpd);D:=-Divisor(ps)-5*Divisor(pd);oldD:=-Divisor(oldps)-5*Divisor(oldpd);for z in op[6] do oldD+:=z[2]*Divisor(RestorePD(z[3]));end for;fast:=MDIsogeniesFastPoints(E,[P,Q],5);assert &+[row[3]:row in fast] eq 6;obs:=[* *];
for row in fast do ET,pts,e:=Explode(row);p:=Get(ET,pts[1],pts[2]);n:=d*e div Degree(p);assert n*Degree(p) eq d*e;D+:=n*Divisor(p);Append(~obs,[e,n,Degree(p)]);end for;assert Degree(D) eq 0 and D eq oldD;print "Y228_FAST_EXACT_OLD_PRIMES_AND_AGGREGATE_DIVISOR_MATCH",ci;print "Y228_FAST_OPERATOR_READY",ci,obs,Cputime(tt);st:=Cputime();hs:=#Basis(D);print "Y228_FAST_BASIS_RESULT",ci,hs,Cputime(st),Cputime(tt);assert hs in [0,1];Write("work/deg10/continuation_20261031b/Y228_shared/fast_inverse_profile_summary.m",Sprint([*ci,obs,hs,Cputime(tt)*]):Overwrite:=true);print "D31B_Y228_FAST_INVERSE_OLD_PRIME_COMPARISON_COMPLETE";quit;
